(async()=>{
const out={},test=(name,f)=>{try{out[name]=f()}catch(e){out[name]={error:e.name,message:e.message}}};
test('selectors',()=>{const form=document.createElement('form');form.innerHTML='<select><option>a</option><option>b</option></select><input type=radio name=x><input type=radio name=x>';document.body.appendChild(form);const select=form.firstElementChild,radios=Array.from(form.querySelectorAll('input')),calls=[];const ps=[Document.prototype,Element.prototype,DocumentFragment.prototype],old=ps.map(p=>p.querySelectorAll);ps.forEach((p,i)=>p.querySelectorAll=function(s){calls.push(s);return old[i].call(this,s)});let values;try{values=[select.length,select.options.length,select.selectedIndex,select.value,form.length,form.elements.length,document.images.length,document.forms.length];radios[0].checked=true;radios[1].checked=true;values.push(radios[0].checked,radios[1].checked)}finally{ps.forEach((p,i)=>p.querySelectorAll=old[i]);form.remove()}return {values,calls}});
test('nonce',()=>{const rows=[];const snap=(label,s)=>rows.push({label,nonce:s.nonce,attr:s.getAttribute('nonce'),has:s.hasAttribute('nonce'),html:s.outerHTML});for(const tag of ['script','style','div']){const s=document.createElement(tag);s.nonce='abc';snap(tag+' detached',s);document.body.appendChild(s);snap(tag+' connected',s);s.setAttribute('nonce','def');snap(tag+' attribute',s);s.nonce='ghi';snap(tag+' property',s);const c=s.cloneNode(true);snap(tag+' clone',c);s.remove();snap(tag+' removed',s);s.removeAttribute('nonce');snap(tag+' cleared',s)}return rows});
test('serialization',()=>{const out=[];for(const tag of ['div','script','style','textarea','pre']){const e=document.createElement(tag);e.setAttribute('data-test',`"'&<>${String.fromCharCode(160)}`);e.textContent=`"'&<>${String.fromCharCode(160)}`;out.push([tag,e.innerHTML,e.outerHTML])}const e=document.createElement('template');e.innerHTML='<p data-a="&quot;">&nbsp; &amp;</p>';out.push(['template',e.innerHTML,e.outerHTML]);return out});
test('geometry',()=>{const rows=[];for(const [name,css]of [['absolute','position:absolute;left:13px;top:17px'],['negative','position:absolute;left:-13px;top:-17px'],['translate','position:absolute;left:13px;top:17px;transform:translate(7px,9px)'],['fixed','position:fixed;left:13px;top:17px'],['scale','position:absolute;left:13px;top:17px;transform:scale(2)'],['hidden','display:none;position:absolute;left:13px;top:17px']]){const e=document.createElement('div');e.style.cssText='width:80px;height:20px;'+css;document.body.appendChild(e);const r=e.getBoundingClientRect();rows.push([name,r.x,r.y,r.width,r.height,e.offsetLeft,e.offsetTop,e.offsetWidth,e.offsetHeight]);e.remove()}return rows});
return out;
})()
